/** What each request a client sends takes, and what the Host answers. */
export interface HostRequests {
  "host/hello": { params: HelloRequest; result: HelloResponse };
  "host/challenge": { params: ChallengeRequest; result: ChallengeResponse };
  "host/status": { params: StatusRequest; result: HostStatus };
  "host/drain": { params: DrainRequest; result: DrainResponse };
  "host/shutdown": { params: ShutdownRequest; result: Empty };
  "agents/list": { params: ListAgentsRequest; result: ListAgentsResponse };
  "agents/get": { params: GetAgentRequest; result: GetAgentResponse };
  "agents/authenticate": { params: AuthenticateAgentRequest; result: Empty };
  "agents/terminalSignIn": { params: TerminalSignInRequest; result: TerminalSignInResponse };
  "agents/logout": { params: LogoutAgentRequest; result: Empty };
  "agents/update": { params: UpdateAgentRequest; result: UpdateAgentResponse };
  "devices/offer": { params: OfferDeviceRequest; result: OfferDeviceResponse };
  "devices/list": { params: ListDevicesRequest; result: ListDevicesResponse };
  "devices/revoke": { params: RevokeDeviceRequest; result: Empty };
  "files/list": { params: ListFilesRequest; result: ListFilesResponse };
  "sessions/list": { params: ListSessionsRequest; result: ListSessionsResponse };
  "sessions/get": { params: GetSessionRequest; result: GetSessionResponse };
  "sessions/watch": { params: WatchSessionsRequest; result: WatchSessionsResponse };
  "sessions/unwatch": { params: UnwatchSessionsRequest; result: Empty };
  "session/create": { params: CreateSessionRequest; result: SessionState };
  "session/attach": { params: AttachSessionRequest; result: AttachSessionResponse };
  "session/detach": { params: DetachSessionRequest; result: Empty };
  "session/close": { params: CloseSessionRequest; result: Empty };
  "session/delete": { params: DeleteSessionRequest; result: Empty };
  "session/setMode": { params: SetModeRequest; result: Empty };
  "session/setConfigOption": { params: SetConfigOptionRequest; result: SetSessionConfigOptionResponse };
  "session/reopen": { params: ReopenSessionRequest; result: ReopenSessionResponse };
  "session/rename": { params: RenameSessionRequest; result: Empty };
  "session/run": { params: RunRequest; result: RunResponse };
  "turn/start": { params: StartTurnRequest; result: StartTurnResponse };
  "turn/steer": { params: SteerTurnRequest; result: SteerTurnResponse };
  "turn/cancel": { params: CancelTurnRequest; result: Empty };
  "queue/add": { params: AddQueuedRequest; result: AddQueuedResponse };
  "queue/remove": { params: RemoveQueuedRequest; result: RemoveQueuedResponse };
  "queue/resume": { params: ResumeQueueRequest; result: Empty };
  "pending/answer": { params: AnswerPendingRequest; result: Empty };
  "worktrees/list": { params: ListWorktreesRequest; result: ListWorktreesResponse };
  "worktrees/create": { params: CreateWorktreeRequest; result: CreateWorktreeResponse };
  "worktrees/remove": { params: RemoveWorktreeRequest; result: RemoveWorktreeResponse };
  "worktrees/release": { params: ReleaseWorktreeRequest; result: ReleaseWorktreeResponse };
  "terminals/list": { params: ListTerminalsRequest; result: TerminalsResponse };
  "terminals/watch": { params: WatchTerminalsRequest; result: TerminalsResponse };
  "terminals/unwatch": { params: UnwatchTerminalsRequest; result: Empty };
  "terminals/new": { params: NewTerminalRequest; result: TerminalResponse };
  "terminals/close": { params: CloseTerminalRequest; result: Empty };
  "terminals/setLabel": { params: SetTerminalLabelRequest; result: TerminalResponse };
  "terminals/write": { params: WriteTerminalRequest; result: Empty };
  "terminals/format": { params: FormatTerminalRequest; result: FormatTerminalResponse };
  "terminals/attach": { params: AttachTerminalRequest; result: AttachTerminalResponse };
}

/** What each notification the Host sends carries. */
export interface HostNotifications {
  "session/event": SessionEventNotification;
  "session/changed": SessionChangedNotification;
  "sessions/updated": SessionUpdatedNotification;
  "sessions/removed": SessionRemovedNotification;
  "session/elicitationCompleted": ElicitationCompletedNotification;
  "pending/added": PendingAddedNotification;
  "pending/resolved": PendingResolvedNotification;
  "agents/updateAvailable": UpdateAvailableNotification;
  "devices/paired": DevicePairedNotification;
  "terminals/updated": TerminalUpdatedNotification;
  "terminals/removed": TerminalRemovedNotification;
}

export type HostMethod = keyof HostRequests;
export type HostNotificationMethod = keyof HostNotifications;
